local ItemCatalog = {}

ItemCatalog.Items = {
	["Madeira"] = {
		Name = "Madeira",
		DisplayName = "Madeira",
		MaxStack = 99,
		Description = "Um pedaço de madeira recolhido da costa."
	}
}

function ItemCatalog.GetItem(itemName: string)
	return ItemCatalog.Items[itemName]
end

return ItemCatalog

